import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Resume Mission Failures","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-user-guide/troubleshooting/resume_mission.md","filePath":"zh/qgc-user-guide/troubleshooting/resume_mission.md"}`),a={name:`zh/qgc-user-guide/troubleshooting/resume_mission.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="resume-mission-failures" tabindex="-1">Resume Mission Failures <a class="header-anchor" href="#resume-mission-failures" aria-label="Permalink to “Resume Mission Failures”">​</a></h1><p>The process of resuming a mission after a battery swap is a fairly complex process within QGC.</p><p>The two main areas that are most problematic are:</p><ul><li>The <em>Resume Mission</em> dialog doesn&#39;t display when it should and you are just left with a Start Mission slider.</li><li>The new mission generated from <em>Resume Mission</em> is not quite correct with respect to recreation of waypoints and/or camera commands.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>In order for the <em>QGroundControl</em> development team to debug these issues the following information <strong>must be supplied</strong> in any github issue entered against <em>Resume Mission</em>.</p></div><h2 id="common_steps" tabindex="-1">Common Steps for Resume Mission Dialog/Generation <a class="header-anchor" href="#common_steps" aria-label="Permalink to “Common Steps for Resume Mission Dialog/Generation”">​</a></h2><p>The following steps are required for debugging both types of problems:</p><ol><li><p>Restart QGC</p></li><li><p>Turn on <a href="./../troubleshooting/console_logging.html">console logging</a> with the logging category: <code>QMLControls.GuidedActionsController</code>.</p></li><li><p>Enable <a href="./../settings_view/general.html#miscellaneous">telemetry logging</a> (<strong>Settings &gt; General</strong>).</p></li><li><p>Start the mission.</p></li><li><p>Fly till you need a battery swap.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Alternatively you can attempt to reproduce the problem by manually RTL from the middle of the middle of the mission (though this may not always reproduce the problem).</p></div></li><li><p>一旦载具降落并上锁，你应该 <em>Resume Mission</em> 对话框。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>If not there is a possible bug in QGC.</p></div></li></ol><h3 id="resume-mission-dialog-problems" tabindex="-1">Resume Mission Dialog Problems <a class="header-anchor" href="#resume-mission-dialog-problems" aria-label="Permalink to “Resume Mission Dialog Problems”">​</a></h3><p>For <em>Resume Mission Dialog</em> problems follow the <a href="#common-steps">common steps above</a>, and then:</p><ol><li>Save the <em>App Log</em> to a file.</li><li>Place the <em>App Log</em>, <em>Telemetry Log</em> and <em>Plan File</em> someplace which you can link to in the issue.</li><li>Create the issue with details and links to all three files.</li></ol><h2 id="resume-mission-generation-problems" tabindex="-1">Resume Mission Generation Problems <a class="header-anchor" href="#resume-mission-generation-problems" aria-label="Permalink to “Resume Mission Generation Problems”">​</a></h2><p>For <em>Resume Mission Generation</em> problems follow the <a href="#common-steps">common steps above</a>, and then:</p><ol><li>Click <strong>Resume Mission</strong>.</li><li>The new mission should be generated.</li><li>Go to <a href="./../plan_view/plan_view.html">Plan View</a>.</li><li>Select <strong>Download</strong> from the <em>File/Sync</em> menu.</li><li>Save the <em>Modified Plan</em> to a file.</li><li>Save the <em>App Log</em> to a file.</li><li>Place the <em>App Log</em>, <em>Telemetry Log</em>, <em>Original Plan</em> file and <em>Modified Plan</em> file someplace which you can link to in the issue.</li><li>Create the issue with details and links to all four files.</li></ol>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};